entries[432777] = { ["name"] = "Tome of Unstable Power", ["text"] = "Approximately 1.5 procs per minute\nYour harmful spells have a chance to create 1 to 3 Arcane Illusions of yourself that channel for 3 sec before unleashing Arcane Barrage at your target's location dealing up to ( 1343 * 1.1) Arcane damage to all enemies in the area." }
