entries[432962] = { ["name"] = "Algari Flask Cauldron", ["text"] = "2 sec cast 3\nReagents:\nCrystalforged Cauldron , Coreway Catalyst (25), Vial of Kaheti Oils (3), Gilded Vial (20), Harmonious Horticulture (8)\nOptional Reagents:\nSpecialization:\nFantastic Flasks (30)\n\nAlgari Flask Cauldron\nBinds to Warband\n\nUse: Place a cauldron that allows party and raid members to take flasks of their choosing from among the recipes known by your Warband. Only alchemists with the cauldron recipe will contribute.\n\nThe cauldron lasts for 5 min and has 40 charges. You will receive the Crystalforged Cauldron back once used.\n71" }
entries[432963] = { ["name"] = "Algari Potion Cauldron", ["text"] = "2 sec cast 3\nReagents:\nCrystalforged Cauldron , Coreway Catalyst (40), Viridian Charmcap (5), Gilded Vial (80), Harmonious Horticulture (8)\nOptional Reagents:\nSpecialization:\nPotent Potions (30)\n\nAlgari Potion Cauldron\nBinds to Warband\n\nUse: Place a cauldron that allows party and raid members to take potions of their choosing from among the recipes known by your Warband. Only alchemists with the cauldron recipe will contribute.\n\nThe cauldron lasts for 5 min and has 80 charges. Each charge grants 5 potions. You will receive the Crystalforged Cauldron back once used.\n71" }
