entries[433292] = { ["name"] = "Prepare Algari Potion Cauldron", ["text"] = "5 yd range\n1 sec cast\nPlace a cauldron that allows party and raid members to take potions of their choosing from among the recipes known by your Warband. Only alchemists with the cauldron recipe will contribute.\n\nThe cauldron lasts for 5 min and has 80 charges. Each charge grants 5 potions. You will receive the Crystalforged Cauldron back once used." }
